(function installStaffAdminCard(){
  const api=window.__crmApi;
  if(typeof api!=='function'||window.__staffAdminCardLoaded)return;
  window.__staffAdminCardLoaded=true;
  const esc=(value)=>String(value??'').replace(/[&<>"']/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
  const phones=(items)=>Array.isArray(items)?items.filter((item)=>item&&item.number).map((item,index)=>({label:String(item.label||'Рабочий'),number:String(item.number||''),primary:Boolean(item.primary)||index===0})):[];
  const open=async(id)=>{
    let person;try{person=await api('/api/staff/'+encodeURIComponent(id)+'/profile');}catch(_){if(typeof window.portalNotice==='function')window.portalNotice('Не удалось открыть карточку сотрудника','error');return;}
    const roleLabels={owner:'Владелец',admin:'Администратор',senior_bartender:'Старший бармен',senior_hookah_master:'Старший кальянщик',bartender:'Бармен',hookah_master:'Кальянщик',developer:'Разработчик'};const canAssignRole=portalUser.role==='owner'||!['owner','admin','developer'].includes(person.role);const roleOptions=(portalUser.role==='owner'?['admin','senior_bartender','senior_hookah_master','bartender','hookah_master','developer']:[person.role,'senior_bartender','senior_hookah_master','bartender','hookah_master']).filter((role,index,all)=>role&&all.indexOf(role)===index).map((role)=>'<option value=\"'+role+'\" '+(person.role===role?'selected':'')+'>'+roleLabels[role]+'</option>').join('');const modal=document.createElement('div');modal.className='modal staff-admin-modal open';modal.innerHTML='<form class="staff-admin-box"><div class="modal-head"><div><h2>Карточка сотрудника</h2><small>Контакты и данные доступа</small></div><button type="button" class="staff-admin-close" aria-label="Закрыть">×</button></div><div class="staff-admin-identity"><span class="staff-admin-avatar">'+(person.avatarUrl?'<img src="'+esc(person.avatarUrl)+'" alt="">':esc(String(person.name||'?').slice(0,1)))+'</span><div><b>'+esc(person.name)+'</b><small>'+esc(roleLabels[person.role]||person.role)+'</small></div></div><label class="staff-admin-field">ФИО<input name="name" value="'+esc(person.name||'')+'" maxlength="120" required></label><label class="staff-admin-field">Роль<select name="role" '+(canAssignRole?'':'disabled')+'>'+roleOptions+'</select></label><label class="staff-admin-field">Telegram<input name="telegram" value="'+esc(person.telegram||'')+'" placeholder="@username или https://t.me/username"></label><label class="staff-admin-field">Дата начала работы<input name="employmentStartedAt" type="date" value="'+esc(person.employmentStartedAt||'')+'"></label><label class="staff-admin-field">Рабочие заметки<textarea name="workNotes" maxlength="4000" rows="3" placeholder="Внутренние заметки для администраторов">'+esc(person.workNotes||'')+'</textarea></label><section class="staff-admin-pin"><div class="staff-admin-pin-head"><b>PIN блокировки экрана</b><span class="staff-admin-pin-state">'+ (person.pinConfigured ? 'Настроен' : 'Не настроен') + '</span></div><small>Нужен только после блокировки экрана, для входа используется пароль.</small><div class="staff-admin-pin-grid"><label>Новый PIN<input name="pin_new" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" placeholder="••••"></label><label>Повторите PIN<input name="pin_confirm" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" placeholder="••••"></label></div></section><div class="staff-admin-phone-head"><b>Телефоны</b><button type="button" class="staff-admin-add">Добавить номер</button></div><div class="staff-admin-phone-list"></div><div class="staff-admin-passport">'+(person.passportData?'<b>Паспортные данные доступны уполномоченному администратору</b>':'<small>Паспортные данные скрыты или не заполнены</small>')+'</div><p class="form-message staff-admin-message" role="alert"></p><div class="staff-admin-actions"><button type="button" class="secondary staff-admin-cancel">Отмена</button><button class="button primary" type="submit">Сохранить изменения</button></div></form>';
    document.body.append(modal);const form=modal.querySelector('form'),list=modal.querySelector('.staff-admin-phone-list');
    const add=(item={label:'Дополнительный',number:'',primary:false})=>{if(list.children.length>=5)return;const row=document.createElement('div');row.className='staff-admin-phone-row';row.innerHTML='<select><option>Рабочий</option><option>Личный</option><option>Резервный</option><option>Дополнительный</option></select><input type="tel" placeholder="+7 (___) ___-__-__"><label><input type="radio" name="staff_admin_primary"> основной</label><button type="button" class="staff-admin-phone-remove" aria-label="Удалить номер" title="Удалить номер"><svg class="icon" aria-hidden="true"><use href="/assets/tabler-icons.svg#x"></use></svg></button>';row.querySelector('select').value=item.label||'Дополнительный';row.querySelector('input[type="tel"]').value=item.number||'';row.querySelector('input[type="radio"]').checked=Boolean(item.primary);row.querySelector('button').onclick=()=>{if(list.children.length>1){row.remove();modal.querySelector('.staff-admin-add').disabled=false;}};list.append(row);modal.querySelector('.staff-admin-add').disabled=list.children.length>=5;};
    const passportSummary=person.passportData?(()=>{const data=person.passportData||{};const number=String(data.number||'');const masked=number.length>4?'•••• '+number.slice(-4):number||'не указан';return '<b>Паспорт: '+esc(masked)+'</b><small>Дата выдачи: '+esc(data.issuedAt||'не указана')+' · '+esc(data.issuer||'кем выдан не указан')+'</small>';})():'<small>Паспортные данные скрыты или не заполнены</small>';const passportBlock=modal.querySelector('.staff-admin-passport');const canEditPassport=portalUser.role==='owner'||(portalUser.role==='admin'&&window.portalPermissions?.has?.('staff_sensitive'));if(passportBlock)passportBlock.innerHTML=canEditPassport?'<details open><summary>Кадровые данные</summary><div class="staff-admin-passport-grid"><label>Серия и номер<input name="passport_number" inputmode="numeric" autocomplete="off" value="'+esc(person.passportData?.number||'')+'"></label><label>Дата выдачи<input name="passport_issued_at" type="date" value="'+esc(person.passportData?.issuedAt||'')+'"></label><label>Кем выдан<input name="passport_issuer" value="'+esc(person.passportData?.issuer||'')+'"></label></div><small>Данные видны владельцу и администратору и записываются в аудит.</small></details>':passportSummary;const initial=phones(person.phoneNumbers);(initial.length?initial:[{label:'Рабочий',number:'',primary:true}]).forEach(add);const close=()=>modal.remove();modal.querySelector('.staff-admin-close').onclick=close;modal.querySelector('.staff-admin-cancel').onclick=close;modal.querySelector('.staff-admin-add').onclick=()=>add();modal.onclick=(event)=>{if(event.target===modal)close();};
    form.onsubmit=async(event)=>{event.preventDefault();if(form.dataset.submitting==='1')return;const value=form.elements.telegram.value.trim();if(value&&!/^(@[A-Za-z0-9_]{5,32}|https:\/\/t\.me\/[A-Za-z0-9_]{5,32}\/?$)/.test(value)){modal.querySelector('.staff-admin-message').textContent='Проверьте ссылку Telegram';return;}const phoneNumbers=[...list.querySelectorAll('.staff-admin-phone-row')].map((row)=>({label:row.querySelector('select').value,number:row.querySelector('input[type="tel"]').value.trim(),primary:row.querySelector('input[type="radio"]').checked})).filter((item)=>item.number);if(phoneNumbers.length>5){modal.querySelector('.staff-admin-message').textContent='Можно сохранить не более пяти номеров';return;}if(phoneNumbers.length&&phoneNumbers.filter((item)=>item.primary).length!==1){modal.querySelector('.staff-admin-message').textContent='Выберите один основной номер';return;}form.dataset.submitting='1';const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{const newPin=form.elements.pin_new.value.trim();const pinConfirm=form.elements.pin_confirm.value.trim();if((newPin||pinConfirm)&&(!/^\d{4}$/.test(newPin)||newPin!==pinConfirm)){form.dataset.submitting='0';if(submit)submit.disabled=false;modal.querySelector('.staff-admin-message').textContent='Введите одинаковый PIN из 4 цифр';return;}await api('/api/staff/'+encodeURIComponent(id)+'/profile',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:form.elements.name.value.trim(),...(canAssignRole?{role:form.elements.role.value}:{}),telegram:value,phoneNumbers,employmentStartedAt:form.elements.employmentStartedAt.value||null,workNotes:form.elements.workNotes.value.trim(),...(canEditPassport?{passportData:{number:form.elements.passport_number?.value?.trim()||'',issuedAt:form.elements.passport_issued_at?.value||'',issuer:form.elements.passport_issuer?.value?.trim()||''}}:{})})});if(newPin)await api('/api/staff/'+encodeURIComponent(id)+'/pin',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({pin:newPin})});close();if(typeof window.__refreshStaffList==='function')window.__refreshStaffList();}catch(error){const reason=String(error?.payload?.error||'');form.dataset.submitting='0';if(submit)submit.disabled=false;modal.querySelector('.staff-admin-message').textContent=reason==='staff_management_required'?'Недостаточно прав для кадровых полей':reason==='staff_role_assignment_required'?'Назначать администраторов и разработчиков может только владелец':reason==='owner_staff_protected'?'Карточку владельца изменяет только владелец':reason==='one_primary_phone_required'?'Выберите один основной номер':reason==='invalid_phone_numbers'?'Проверьте телефоны: до пяти номеров, один основной':reason==='staff_passport_key_required'?'Не настроен ключ шифрования паспортных данных':reason==='staff_profile_save_failed'?'База данных отклонила изменения карточки':reason==='invalid_staff_pin_format'?'PIN должен состоять из 4 цифр':reason==='staff_pin_save_failed'?'Не удалось сохранить PIN':reason==='staff_pin_key_required'?'Не настроен ключ шифрования PIN':reason==='HTTP 409'?'Сервер отклонил изменения карточки':`Не удалось сохранить карточку${reason?` (${reason})`:''}`;}};
  };
  document.addEventListener('click',(event)=>{const button=event.target.closest('.staff-edit');if(button)open(button.dataset.staff);});
})();
